Proceso Diferencia
    Definir Mutable a Como Entero <- 0;
    Definir Mutable b Como Entero <- 0;
    Leer a;
    Leer b;
    Definir resultadoFinal Como Entero <- a - b;
    Escribir resultadoFinal;
FinProceso

